import { forwardRef, isValidElement, useImperativeHandle, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Img, Interactive, Sequence, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

type BackdropFill =
  | { type: "color"; value: string }
  | { type: "gradient"; value: string }
  | { type: "image"; src: string; fit?: "cover" | "contain" };

interface BackdropProps {
  fill?: BackdropFill | ReactNode;
  padding?: number;
  radius?: number;
  shadow?: string;
  children?: ReactNode;
  className?: string;
}

const DEFAULT_FILL: BackdropFill = { type: "color", value: "#0a0a0a" };

function FillLayer({ fill }: { fill: BackdropFill }) {
  if (fill.type === "image") {
    return (
      <AbsoluteFill>
        <Img
          src={fill.src}
          style={{
            width: "100%",
            height: "100%",
            objectFit: fill.fit ?? "cover",
          }}
        />
      </AbsoluteFill>
    );
  }

  return <AbsoluteFill style={{ background: fill.value }} />;
}

function BackdropBase({
  fill,
  padding = 4,
  radius = 1,
  shadow = "0 20px 60px rgba(0,0,0,0.4)",
  children,
  className,
}: BackdropProps) {
  const { width } = useVideoConfig();

  const paddingPx = (padding / 100) * width;
  const radiusPx = (radius / 100) * width;

  const fillLayer = isValidElement(fill) ? (
    <AbsoluteFill>{fill}</AbsoluteFill>
  ) : (
    <FillLayer fill={(fill as BackdropFill | undefined) ?? DEFAULT_FILL} />
  );

  return (
    <AbsoluteFill className={className}>
      {fillLayer}
      {children != null && (
        <div
          style={{
            position: "absolute",
            inset: paddingPx,
            overflow: "hidden",
            borderRadius: radiusPx,
            display: "flex",
            ...(shadow === "" ? {} : { boxShadow: shadow }),
          }}
        >
          <div style={{ width: "100%", height: "100%" }}>{children}</div>
        </div>
      )}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  fillType: {
    type: "enum",
    default: "gradient",
    variants: {
      color: {},
      gradient: {},
      image: {},
    },
    description: "Fill type",
  },
  color: {
    type: "color",
    default: "#6366f1",
    description: "Color",
  },
  gradient: {
    type: "text-content",
    default: "linear-gradient(135deg, #6366f1 0%, #a855f7 100%)",
    description: "Gradient (CSS)",
  },
  image: {
    type: "text-content",
    default: "/hero.png",
    description: "Image URL",
  },
  padding: {
    type: "number",
    min: 0,
    max: 12,
    step: 0.5,
    default: 4,
    description: "Padding",
    hiddenFromList: false,
  },
  radius: {
    type: "number",
    min: 0,
    max: 4,
    step: 0.25,
    default: 1,
    description: "Radius",
    hiddenFromList: false,
  },
  shadow: {
    type: "text-content",
    default: "0 20px 60px rgba(0,0,0,0.4)",
    description: "Shadow",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["fillType","color","gradient","image","padding","radius","shadow"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  fillType: "gradient",
  color: "#6366f1",
  gradient: "linear-gradient(135deg, #6366f1 0%, #a855f7 100%)",
  image: "/hero.png",
  padding: 4,
  radius: 1,
  shadow: "0 20px 60px rgba(0,0,0,0.4)",
};

type BackdropElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BackdropBase>;

const BackdropInner = forwardRef<
  HTMLDivElement,
  BackdropElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Backdrop>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BackdropBase
          {...(componentProps as unknown as ComponentProps<typeof BackdropBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Backdrop = Interactive.withSchema({
  Component: BackdropInner,
  componentName: "<Backdrop>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
